INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'opera', 'n.', '/ˈɒp(ə)rə/', '歌剧', 'Peking Opera combines music, singing and acting on one stage.', '京剧把音乐、演唱和表演结合在一个舞台上。', 'Stage and Screen', 1, 0, 'senior', 'wordlist', 'required2', 'U4', 'Peking Opera', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'movement', 'n.', '/ˈmuːvmənt/', '动作;运动', 'Every movement of the dancers told part of the story.', '舞者的每个动作都讲述着故事的一部分。', 'Stage and Screen', 2, 0, 'senior', 'wordlist', 'required2', 'U4', 'graceful movement', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'aspect', 'n.', '/ˈæspekt/', '方面', 'The costumes were the aspect of the opera that impressed me most.', '戏服是这部歌剧中最令我印象深刻的方面。', 'Stage and Screen', 3, 0, 'senior', 'wordlist', 'required2', 'U4', 'an aspect of the show', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'version', 'n.', '/ˈvɜːʃ(ə)n/', '版本;改编', 'This film is a modern version of a classic play.', '这部电影是一部经典戏剧的现代版本。', 'Stage and Screen', 4, 0, 'senior', 'wordlist', 'required2', 'U4', 'the film version', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'string', 'n.', '/strɪŋ/', '(乐器的)弦;细绳', 'The jinghu is a small instrument with only two strings.', '京胡是一种只有两根弦的小乐器。', 'Stage and Screen', 5, 0, 'senior', 'wordlist', 'required2', 'U4', 'two strings', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'female', 'adj.', '/ˈfiːmeɪl/', '女(性)的;雌性的', 'Some of the female voices were so high that they amazed me.', '一些女声高得令我惊叹。', 'Stage and Screen', 6, 0, 'senior', 'wordlist', 'required2', 'U4', 'a female role', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'technique', 'n.', '/tekˈniːk/', '技巧;手法', 'Using simple techniques, the actors turned a bare stage into a palace.', '运用简单的手法,演员们把空荡的舞台变成了宫殿。', 'Stage and Screen', 7, 0, 'senior', 'wordlist', 'required2', 'U4', 'stage techniques', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'transform', 'v.', '/trænsˈfɔːm/', '使改观;使转化', 'A few clever props can transform an empty stage into a forest.', '几件巧妙的道具就能把空舞台变成一片森林。', 'Stage and Screen', 8, 0, 'senior', 'wordlist', 'required2', 'U4', 'transform the stage', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'universe', 'n.', '/ˈjuːnɪvɜːs/', '宇宙;万物', 'On stage, a single screen seemed to open up a whole universe.', '在舞台上,仅一块幕布似乎就展开了整个宇宙。', 'Stage and Screen', 9, 0, 'senior', 'wordlist', 'required2', 'U4', 'the whole universe', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'incredible', 'adj.', '/ɪnˈkredɪb(ə)l/', '难以置信的;惊人的', 'Watching the actor do a backflip on stage was simply incredible.', '看演员在舞台上后空翻简直令人难以置信。', 'Stage and Screen', 10, 0, 'senior', 'wordlist', 'required2', 'U4', 'an incredible scene', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'energetic', 'adj.', '/ˌenəˈdʒetɪk/', '精力充沛的;充满活力的', 'The dance was so energetic that the performers seemed like athletes.', '这段舞蹈充满活力,演员们看起来像运动员。', 'Stage and Screen', 11, 0, 'senior', 'wordlist', 'required2', 'U4', 'an energetic performance', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'clap', 'v.', '/klæp/', '鼓掌;拍(手)', 'Everyone began to clap as the curtain came down.', '幕布落下时,大家都开始鼓掌。', 'Stage and Screen', 12, 0, 'senior', 'wordlist', 'required2', 'U4', 'clap loudly', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'edge', 'n.', '/edʒ/', '边缘', 'The exciting story kept us on the edge of our seats.', '扣人心弦的故事让我们一直坐在座位边缘。', 'Stage and Screen', 13, 0, 'senior', 'wordlist', 'required2', 'U4', 'on the edge of one''s seat', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'emotion', 'n.', '/ɪˈməʊʃ(ə)n/', '强烈的情感', 'Feeling the strong emotions in the play, I almost cried.', '感受到剧中强烈的情感,我几乎哭了。', 'Stage and Screen', 14, 0, 'senior', 'wordlist', 'required2', 'U4', 'strong emotions', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'anger', 'n.', '/ˈæŋɡə/', '愤怒;怒火', 'The actor showed the prince''s anger with just one look.', '演员只用一个眼神就表现出王子的愤怒。', 'Stage and Screen', 15, 0, 'senior', 'wordlist', 'required2', 'U4', 'love and anger', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'combine', 'v.', '/kəmˈbaɪn/', '(使)结合;(使)组合', 'The show combines singing, dancing and drama with great effect.', '这场演出把演唱、舞蹈和戏剧出色地结合在一起。', 'Stage and Screen', 16, 0, 'senior', 'wordlist', 'required2', 'U4', 'combine music and drama', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'poetry', 'n.', '/ˈpəʊɪtri/', '诗;诗歌', 'The opera brings together music, drama and poetry.', '这部歌剧把音乐、戏剧和诗歌融为一体。', 'Stage and Screen', 17, 0, 'senior', 'wordlist', 'required2', 'U4', 'music and poetry', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'explosive', 'adj.', '/ɪkˈspləʊsɪv/', '爆发(式)的;爆炸的', 'The final scene ended with explosive energy and colour.', '最后一幕以爆发式的能量和色彩收尾。', 'Stage and Screen', 18, 0, 'senior', 'wordlist', 'required2', 'U4', 'with explosive effect', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'applaud', 'v.', '/əˈplɔːd/', '(为……)鼓掌;赞赏', 'The whole audience stood up to applaud the actors.', '全场观众起立为演员们鼓掌。', 'Stage and Screen', 19, 0, 'senior', 'wordlist', 'required2', 'U4', 'applaud the actors', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'grateful', 'adj.', '/ˈɡreɪtf(ə)l/', '感激的;感谢的', 'Seeing my family in the audience, I felt confident and grateful.', '看到家人在观众席里,我感到自信又感激。', 'Stage and Screen', 20, 0, 'senior', 'wordlist', 'required2', 'U4', 'feel grateful', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'extremely', 'adv.', '/ɪkˈstriːmli/', '极其;非常', 'Before going on stage, I felt extremely nervous.', '上台之前,我感到极其紧张。', 'Stage and Screen', 21, 0, 'senior', 'wordlist', 'required2', 'U4', 'extremely nervous', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'overcome', 'v.', '/ˌəʊvəˈkʌm/', '克服(困难);控制(感情)', 'With my teacher''s help, I overcame my fears and finished the play.', '在老师的帮助下,我克服了恐惧,演完了这出戏。', 'Stage and Screen', 22, 0, 'senior', 'wordlist', 'required2', 'U4', 'overcome one''s fears', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'ballet', 'n.', '/ˈbæleɪ/', '芭蕾舞;芭蕾舞剧', 'Last night I went to watch the ballet The Peony Pavilion.', '昨晚我去看了芭蕾舞剧《牡丹亭》。', 'Stage and Screen', 23, 0, 'senior', 'wordlist', 'required2', 'U4', 'watch a ballet', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'absorbed', 'adj.', '/əbˈsɔːbd/', '专心致志的;全神贯注的', 'As soon as the curtain rose, I was completely absorbed.', '幕布一升起,我就完全入了迷。', 'Stage and Screen', 24, 0, 'senior', 'wordlist', 'required2', 'U4', 'be absorbed in', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'romantic', 'adj.', '/rəʊˈmæntɪk/', '浪漫的', 'The dance was full of colour and romantic symbols.', '这段舞蹈充满色彩与浪漫的象征。', 'Stage and Screen', 25, 0, 'senior', 'wordlist', 'required2', 'U4', 'romantic symbols', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'comedy', 'n.', '/ˈkɒmɪdi/', '喜剧', 'We laughed all evening at the comedy show.', '在喜剧表演上我们笑了一整晚。', 'Stage and Screen', 26, 0, 'senior', 'wordlist', 'required2', 'U4', 'a comedy show', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'documentary', 'n.', '/ˌdɒkjʊˈment(ə)ri/', '纪录片', 'The nature documentary showed leopards in the wild.', '这部自然纪录片展现了野外的豹子。', 'Stage and Screen', 27, 0, 'senior', 'wordlist', 'required2', 'U4', 'a nature documentary', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'absolutely', 'adv.', '/ˈæbsəluːtli/', '完全地;绝对地', 'Last night''s episode was absolutely wonderful.', '昨晚那一集绝对精彩。', 'Stage and Screen', 28, 0, 'senior', 'wordlist', 'required2', 'U4', 'absolutely wonderful', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'episode', 'n.', '/ˈepɪsəʊd/', '(电视剧的)一集', 'I can''t wait to watch the final episode of the talent show.', '我等不及要看这档选秀节目的最后一集了。', 'Stage and Screen', 29, 0, 'senior', 'wordlist', 'required2', 'U4', 'the final episode', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'appealing', 'adj.', '/əˈpiːlɪŋ/', '有吸引力的;有趣的', 'The leopards are such appealing creatures that the show is a joy to watch.', '豹子是如此惹人喜爱,这部片子看着真令人愉快。', 'Stage and Screen', 30, 0, 'senior', 'wordlist', 'required2', 'U4', 'an appealing character', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'definitely', 'adv.', '/ˈdefɪnɪtli/', '肯定地;确切地', 'The Monkey King is definitely a hero to many children.', '对许多孩子来说,孙悟空绝对是个英雄。', 'Stage and Screen', 31, 0, 'senior', 'wordlist', 'required2', 'U4', 'definitely a hero', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'plot', 'n.', '/plɒt/', '(故事的)情节', 'I enjoy this film for its creative plot and clever settings.', '我喜欢这部电影有创意的情节和巧妙的场景。', 'Stage and Screen', 32, 0, 'senior', 'wordlist', 'required2', 'U4', 'a creative plot', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'rude', 'adj.', '/ruːd/', '粗鲁的;无礼的', 'The talk show host was so rude that he hardly let his guests speak.', '那个脱口秀主持人太无礼了,几乎不让嘉宾说话。', 'Stage and Screen', 33, 0, 'senior', 'wordlist', 'required2', 'U4', 'a rude host', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'transport', 'n.', '/ˈtrænspɔːt/', '交通运输(系统)', 'We took public transport to reach the festival site.', '我们乘公共交通到达了音乐节场地。', 'Stage and Screen', 34, 0, 'senior', 'wordlist', 'required2', 'U4', 'public transport', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'arrangement', 'n.', '/əˈreɪndʒmənt/', '安排;筹划', 'Josh made all the arrangements for our trip to the concert.', '去演唱会的所有安排都是Josh做的。', 'Stage and Screen', 35, 0, 'senior', 'wordlist', 'required2', 'U4', 'make arrangements', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'brief', 'adj.', '/briːf/', '短暂的;简短的', 'Even a brief look at the book shows how much the film left out.', '即使简单看一眼原著,也能发现电影遗漏了多少内容。', 'Stage and Screen', 36, 0, 'senior', 'wordlist', 'required2', 'U4', 'a brief look', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'turkey', 'n.', '/ˈtɜːki/', '(电影或戏剧的)失败之作', 'Too often great books are turned into cinematic turkeys.', '好书常常被拍成电影界的失败之作。', 'Stage and Screen', 37, 0, 'senior', 'wordlist', 'required2', 'U4', 'a cinematic turkey', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'escape', 'v.', '/ɪˈskeɪp/', '逃离;摆脱;避开', 'Even the Harry Potter films could not escape from leaving out parts of the story.', '连《哈利·波特》电影也无法避免遗漏部分故事情节。', 'Stage and Screen', 38, 0, 'senior', 'wordlist', 'required2', 'U4', 'escape from', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'disappointed', 'adj.', '/ˌdɪsəˈpɔɪntɪd/', '失望的;沮丧的', 'Fans of the book were disappointed not to see their favourite characters.', '原著粉丝因没看到喜爱的角色而失望。', 'Stage and Screen', 39, 0, 'senior', 'wordlist', 'required2', 'U4', 'be disappointed', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'extent', 'n.', '/ɪkˈstent/', '程度', 'The choice of actress changed opinions of the film to some extent.', '女演员的人选在某种程度上改变了人们对这部电影的看法。', 'Stage and Screen', 40, 0, 'senior', 'wordlist', 'required2', 'U4', 'to some extent', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'original', 'adj.', '/əˈrɪdʒɪn(ə)l/', '原先的;最初的;原版的', 'Perhaps we should judge a film on its own, not against the original book.', '也许我们该就电影本身来评价它,而不是拿它与原著比较。', 'Stage and Screen', 41, 0, 'senior', 'wordlist', 'required2', 'U4', 'the original source', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'fictional', 'adj.', '/ˈfɪkʃ(ə)nəl/', '虚构的;小说(中)的', 'In the film, Mia learns she is the princess of a fictional kingdom.', '在电影里,Mia得知自己是一个虚构王国的公主。', 'Stage and Screen', 42, 0, 'senior', 'wordlist', 'required2', 'U4', 'a fictional kingdom', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'awkward', 'adj.', '/ˈɔːkwəd/', '尴尬的;笨拙的;不舒适的', 'Mia is a socially awkward girl who suddenly becomes a princess.', 'Mia是个不善交际的女孩,却突然成了公主。', 'Stage and Screen', 43, 0, 'senior', 'wordlist', 'required2', 'U4', 'feel awkward', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'behave', 'v.', '/bɪˈheɪv/', '表现;举止得体', 'She is taught how to behave at royal events.', '她被教导在王室场合上如何举止得体。', 'Stage and Screen', 44, 0, 'senior', 'wordlist', 'required2', 'U4', 'behave perfectly', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'normal', 'adj.', '/ˈnɔːm(ə)l/', '正常的;平常的', 'Mia must choose between a normal life and life as a princess.', 'Mia必须在平常生活和公主生活之间做出选择。', 'Stage and Screen', 45, 0, 'senior', 'wordlist', 'required2', 'U4', 'a normal life', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'responsibility', 'n.', '/rɪˌspɒnsɪˈbɪlɪti/', '责任', 'The film explores the theme of responsibility in a humorous way.', '这部电影以幽默的方式探讨了责任这一主题。', 'Stage and Screen', 46, 0, 'senior', 'wordlist', 'required2', 'U4', 'explore responsibility', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'absence', 'n.', '/ˈæbs(ə)ns/', '缺乏;没有;不在', 'Courage is not the absence of fear, but doing what is right in spite of it.', '勇气不是没有恐惧,而是不顾恐惧去做正确的事。', 'Stage and Screen', 47, 0, 'senior', 'wordlist', 'required2', 'U4', 'the absence of fear', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (10, 'grief', 'n.', '/ɡriːf/', '悲痛;悲伤', 'Through the music I could feel the prince''s love, anger and grief.', '透过音乐,我能感受到王子的爱、愤怒与悲痛。', 'Stage and Screen', 48, 0, 'senior', 'wordlist', 'required2', 'U4', 'deep grief', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f2u4.01', '①-ing 分词作时间/伴随状语(主动、与谓语同时发生)', 'A2', 10, '外研社版必修第二册 U4 — 当状语的逻辑主语与主句主语一致、且主动地做这个动作、并与主句动作同时发生时,用现在分词(-ing)。它相当于 when/while/as 引导的时间状语或表示伴随的情况。', 1, 'required2', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f2u4.02', '②-ing 分词作原因状语(因为……所以……)', 'A2', 10, '外研社版必修第二册 U4 — 现在分词放在句首(常带 Not / Being / Having)表示原因,相当于 because/as/since 引导的原因状语;逻辑主语主动产生这一原因,故用 -ing,而非被动 -ed、表目的的不定式或谓语动词。', 2, 'required2', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('f2u4.03', '③-ing 与 -ed 分词作状语:主动用 -ing,被动用 -ed', 'A2', 10, '外研社版必修第二册 U4 — 看状语的逻辑主语(=主句主语)与该动作的关系:主语主动发出动作用现在分词(-ing);主语承受动作(常带 by)用过去分词(-ed)。不定式、谓语动词形式均不能作此类状语。', 3, 'required2', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.01'), '____ the sad ending of the play, many in the audience could not hold back their tears.', 'Watching', 'Watched', 'To watch', 'Watch', 'A', '逻辑主语 the audience 主动观看、与流泪同时发生、无连词 → 用现在分词作时间状语;观众不是被看,被动讲不通,不定式表目的与情绪反应不搭。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.01'), 'She walked slowly onto the stage, ____ at the cheering crowd.', 'smiled', 'smiling', 'to smile', 'smiles', 'B', '她一边走一边对观众微笑,表伴随、与主句同时发生 → 现在分词。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.01'), '____ the curtain rise, the whole theatre fell silent at once.', 'Seen', 'To see', 'Seeing', 'Saw', 'C', '主语(剧场里的人)主动看到幕布升起,表时间、同时发生 → 现在分词;被动、不定式、谓语动词都不成立。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.01'), 'The old actor sat backstage, ____ quietly to the music from the orchestra.', 'listened', 'to listen', 'listens', 'listening', 'D', '他坐着的同时静静地听音乐,表伴随 → 现在分词。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.01'), '____ for the school play every evening, the students slowly grew more confident.', 'Practising', 'Practised', 'To practise', 'Practise', 'A', '学生主动排练、并随之变得自信,表时间/伴随 → 现在分词;被动讲不通。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.01'), 'He left the cinema in a hurry, ____ his phone behind on the seat.', 'left', 'leaving', 'to leave', 'leaves', 'B', '匆匆离开的同时把手机落下,表伴随结果 → 现在分词。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.01'), '____ the final song, the children clapped and shouted with joy.', 'Heard', 'To hear', 'Hearing', 'Hears', 'C', '孩子们主动听到最后那首歌、并随之欢呼,表时间 → 现在分词;孩子不是被听,被动错。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.01'), 'The dancers moved across the stage, ____ their arms like the wings of a bird.', 'waved', 'to wave', 'waves', 'waving', 'D', '舞者移动的同时挥动手臂,表伴随动作 → 现在分词。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.01'), '____ in the front row, we could see every detail of the performers'' costumes.', 'Sitting', 'Sat', 'To sit', 'Sits', 'A', '我们坐在前排(主动、与看得清同时),表时间/伴随 → 现在分词。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.01'), 'She read the script on the bus, ____ notes in the margin as she went.', 'made', 'making', 'to make', 'makes', 'B', '她读剧本的同时在空白处做笔记,表伴随 → 现在分词。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.01'), '____ along to the music, the audience swayed gently in their seats.', 'Sung', 'To sing', 'Singing', 'Sang', 'C', '观众主动跟唱、同时摇摆,表伴随 → 现在分词;观众不是被唱,被动错。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.01'), 'The host welcomed us warmly, ____ each guest by name.', 'greeted', 'to greet', 'greets', 'greeting', 'D', '主持人欢迎我们的同时逐一称名问候,表伴随 → 现在分词。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.01'), '____ the comedy show, we laughed so hard that our cheeks hurt.', 'Enjoying', 'Enjoyed', 'To enjoy', 'Enjoys', 'A', '我们看喜剧的同时大笑,表时间 → 现在分词;表目的、被动均不合逻辑。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.01'), 'He stood alone in the spotlight, ____ for the music to begin.', 'waited', 'waiting', 'to wait', 'waits', 'B', '他站着的同时等待音乐响起,表伴随 → 现在分词。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.01'), '____ down the lights, the stage manager signalled that the play was about to start.', 'Turned', 'To turn', 'Turning', 'Turns', 'C', '舞台监督主动调暗灯光、随即示意开演,表时间 → 现在分词;他不是被调暗,被动错。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.01'), 'The little girl watched the ballet, ____ her eyes wide with wonder.', 'kept', 'to keep', 'keeps', 'keeping', 'D', '她看芭蕾的同时睁大眼睛,表伴随状态 → 现在分词。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.01'), '____ the theatre after the show, the fans were still talking about the music.', 'Leaving', 'Left', 'To leave', 'Leaves', 'A', '粉丝离开剧院的同时仍在谈论音乐,表时间 → 现在分词。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.01'), 'She practised her lines in front of the mirror, ____ every gesture again and again.', 'repeated', 'repeating', 'to repeat', 'repeats', 'B', '她对镜练台词的同时反复重复每个动作,表伴随 → 现在分词。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.01'), '____ to the radio play in the dark, I could picture every scene in my mind.', 'Listened', 'To listen', 'Listening', 'Listens', 'C', '我听广播剧的同时在脑中想象画面,表时间 → 现在分词。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.01'), 'The crowd poured out of the concert hall, ____ the songs they had just heard.', 'hummed', 'to hum', 'hums', 'humming', 'D', '人群涌出的同时哼着刚听到的歌,表伴随 → 现在分词。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.02'), '____ a huge fan of Peking Opera, Lucy watched the same show three times.', 'Being', 'Been', 'To be', 'Was', 'A', '句首表原因(因为是铁杆戏迷),逻辑主语主动 → 用 Being;Been 不能独立作状语,不定式表目的、谓语动词均错。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.02'), 'Not ____ what the plot was about, the foreign guests felt a little lost.', 'known', 'knowing', 'to know', 'knew', 'B', '因为不了解情节(原因),逻辑主语主动 → Not + 现在分词;被动、不定式、谓语动词都不成立。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.02'), '____ confident about her lines, she stepped onto the stage without any fear.', 'Felt', 'To feel', 'Feeling', 'Feels', 'C', '因为对台词有信心(原因) → 现在分词;她主动产生这种感受,被动错。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.02'), '____ no tickets for the evening show, we decided to watch the matinee instead.', 'Had', 'To have', 'Has', 'Having', 'D', '因为没有晚场票(原因) → Having;谓语动词、不定式都不能这样作状语。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.02'), '____ that the film was based on a true story, many viewers were deeply moved.', 'Knowing', 'Known', 'To know', 'Knew', 'A', '因为得知影片改编自真事(原因) → 现在分词;观众主动知道,被动错。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.02'), '____ up in a family of actors, he loved the theatre from a young age.', 'Grown', 'Growing', 'To grow', 'Grows', 'B', '因为在演员家庭长大(原因) → 现在分词;grow up 为主动行为,被动错。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.02'), 'Not ____ the language of the opera, the tourists relied on the subtitles to follow the story.', 'understood', 'to understand', 'understanding', 'understands', 'C', '因为听不懂歌剧语言(原因) → Not + 现在分词。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.02'), '____ such a moving story, the documentary touched audiences all over the world.', 'Told', 'To tell', 'Tells', 'Telling', 'D', '因为讲述了如此动人的故事(原因),纪录片主动讲述 → 现在分词;被动 Told 讲不通。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.02'), '____ from a bad cold, the lead singer had to cancel the concert.', 'Suffering', 'Suffered', 'To suffer', 'Suffers', 'A', '因为得了重感冒(原因),suffer from 为主动 → 现在分词。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.02'), '____ how difficult the dance was, I admired the performers even more.', 'Realised', 'Realising', 'To realise', 'Realises', 'B', '因为意识到舞蹈之难(原因) → 现在分词;我主动意识到,被动错。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.02'), '____ a deep love of cinema, the two friends often watched films together.', 'Shared', 'To share', 'Sharing', 'Shares', 'C', '因为共同热爱电影(原因) → 现在分词;两人主动分享这份喜爱,被动错。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.02'), '____ that the theatre was about to close, we hurried to buy the last tickets.', 'Seen', 'To see', 'Sees', 'Seeing', 'D', '因为看到剧院快关门(原因) → 现在分词;我们主动看到,被动错。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.02'), '____ how the story would end, the readers could not put the novel down.', 'Wondering', 'Wondered', 'To wonder', 'Wonders', 'A', '因为想知道故事结局(原因) → 现在分词。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.02'), '____ both music and drama, she fell in love with opera at once.', 'Enjoyed', 'Enjoying', 'To enjoy', 'Enjoys', 'B', '因为既喜欢音乐又喜欢戏剧(原因) → 现在分词;她主动喜欢,被动错。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.02'), '____ that the show might be cancelled, the fans kept checking their phones.', 'Worried', 'To worry', 'Worrying', 'Worries', 'C', '因为担心演出可能取消(原因) → 现在分词;此处需要句首分词状语,谓语动词形式错。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.02'), '____ time before the show, we grabbed a quick dinner near the theatre.', 'Lacked', 'To lack', 'Lacks', 'Lacking', 'D', '因为开演前时间不够(原因) → 现在分词;lack 在此为主动,被动错。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.02'), '____ romantic stories, she could not wait to see the new ballet.', 'Loving', 'Loved', 'To love', 'Loves', 'A', '因为喜爱浪漫的故事(原因) → 现在分词;她主动喜爱,被动错。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.02'), '____ the last bus home, the fans had to walk back after the concert.', 'Missed', 'Missing', 'To miss', 'Misses', 'B', '因为错过了末班车(原因) → 现在分词;粉丝主动错过(没赶上),被动错。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.02'), '____ to get a good seat, we arrived at the cinema an hour early.', 'Hoped', 'To hope', 'Hoping', 'Hopes', 'C', '因为希望抢到好座位(原因) → 现在分词;Hoping to do 常作原因状语,谓语动词形式错。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.02'), '____ far from any theatre, the village children rarely saw a live play.', 'Lived', 'To live', 'Lives', 'Living', 'D', '因为住得离剧院很远(原因) → 现在分词;live 在此为主动,被动错。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.03'), '____ the orchestra, the conductor raised his hands for silence.', 'Facing', 'Faced', 'To face', 'Faces', 'A', '指挥主动面对乐队 → 现在分词;他不是被面对,过去分词表被动错。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.03'), '____ by the loud applause, the actor came back on stage to bow again.', 'Encouraging', 'Encouraged', 'To encourage', 'Encourages', 'B', '演员被掌声鼓舞(带 by 表被动) → 过去分词;若用 -ing 则成了演员鼓舞掌声,讲不通。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.03'), '____ his lines perfectly, the young actor felt proud of himself.', 'Remembered', 'To remember', 'Remembering', 'Remembers', 'C', '他主动记住台词 → 现在分词;台词被记,但状语逻辑主语是 actor(主动),故不用被动。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.03'), '____ on a famous novel, the film attracted millions of viewers.', 'Basing', 'To base', 'Bases', 'Based', 'D', '影片是被改编自小说,be based on 用被动 → 过去分词;影片不会主动 base,-ing 错。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.03'), '____ a bright red costume, the clown ran around the stage.', 'Wearing', 'Worn', 'To wear', 'Wears', 'A', '小丑主动穿着戏服 → 现在分词;小丑不是被穿,过去分词错。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.03'), '____ by the sad music, the whole audience fell silent.', 'Moving', 'Moved', 'To move', 'Moves', 'B', '观众被悲伤的音乐打动(带 by 表被动) → 过去分词;-ing 会变成观众打动音乐,讲不通。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.03'), '____ a microphone in one hand, the singer walked to the front of the stage.', 'Held', 'To hold', 'Holding', 'Holds', 'C', '歌手主动手持话筒,表伴随 → 现在分词;话筒被握,但状语逻辑主语是歌手(主动),不用被动。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.03'), '____ as the best comedy of the year, the show became hugely popular.', 'Choosing', 'To choose', 'Chooses', 'Chosen', 'D', '节目是被选为年度最佳喜剧 → 过去分词;节目不会主动选,-ing 错。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.03'), '____ his first film at the age of twenty, he soon became famous.', 'Directing', 'Directed', 'To direct', 'Directs', 'A', '他主动执导自己的第一部电影 → 现在分词;他不是被导,过去分词错。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.03'), '____ for the first time in 1790, the opera is still loved by audiences today.', 'Performing', 'Performed', 'To perform', 'Performs', 'B', '歌剧是被首次上演,与主语 opera 是被动关系 → 过去分词;歌剧不会主动表演,-ing 错。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.03'), '____ a heavy box of costumes, the stagehand crossed the dark stage.', 'Carried', 'To carry', 'Carrying', 'Carries', 'C', '舞台工作人员主动搬着戏服箱,表伴随 → 现在分词;他不是被搬,过去分词错。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.03'), '____ in a small mountain village, the documentary showed everyday country life.', 'Filming', 'To film', 'Films', 'Filmed', 'D', '纪录片是被拍摄于小山村,与主语 documentary 是被动关系 → 过去分词;影片不会主动拍,-ing 错。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.03'), '____ the show with a funny joke, the host quickly put everyone at ease.', 'Opening', 'Opened', 'To open', 'Opens', 'A', '主持人主动以笑话开场 → 现在分词;主持人不是被开场,过去分词错。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.03'), '____ by the actor''s sudden appearance, the children screamed with delight.', 'Surprising', 'Surprised', 'To surprise', 'Surprises', 'B', '孩子们被演员突然现身吓到(带 by 表被动) → 过去分词;-ing 会变成孩子使人吃惊,与句意不符。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.03'), '____ the main character, the actress appeared in almost every scene.', 'Played', 'To play', 'Playing', 'Plays', 'C', '女演员主动扮演主角 → 现在分词;她不是被扮演,过去分词错。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.03'), '____ as a king, the old actor walked slowly across the stage.', 'Dressing', 'To dress', 'Dresses', 'Dressed', 'D', 'be dressed as 表“打扮成”,与主语是被动/状态关系 → 过去分词;此处习惯用 dressed,-ing 不合表达。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.03'), '____ the script aloud, the director explained each scene to the cast.', 'Reading', 'Read', 'To read', 'Reads', 'A', '导演主动朗读剧本,表伴随 → 现在分词;剧本被读,但状语逻辑主语是导演(主动),不用被动。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.03'), '____ over a hundred years ago, the play still speaks to today''s audiences.', 'Writing', 'Written', 'To write', 'Writes', 'B', '剧本是被(人)在一百多年前写成,与主语 play 是被动关系 → 过去分词;剧本不会主动写,-ing 错。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.03'), '____ by the weak ending, many viewers left the cinema in silence.', 'Disappointing', 'To disappoint', 'Disappointed', 'Disappoints', 'C', '观众对软弱的结尾感到失望(带 by 表被动) → 过去分词;-ing 会变成观众令人失望,与句意不符。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='required2' AND unit='U4' AND code='f2u4.03'), '____ in a beautiful old theatre, the play felt even more magical to the audience.', 'Staging', 'To stage', 'Stages', 'Staged', 'D', '戏是被(人)搬上这座剧院上演的,与主语 play 是被动关系 → 过去分词;戏剧不会主动上演,-ing 错。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'When Peking Opera Met Hamlet', 'As a high school student who studies English literature, I thought I knew Hamlet well. After all, I had read Shakespeare''s play many times. Then a Peking Opera version of the story, called The Revenge of Prince Zidan, came to my city, and I had to see it. From the first moment, the music sounded completely new to my ears. At one point I was sure I heard a violin, but it turned out to be a small instrument with two strings. The costumes and masks were amazing, and although the actors sang in Chinese, their movements and faces carried the meaning across to me. The stage itself was almost empty: a single decorated whip stood for a horse. Using such simple techniques, the performers turned a small stage into a whole world. My favourite part was when the prince did a backflip. Feeling the love, anger and grief in the show, I had no trouble recognising the story of Hamlet.', '记叙·京剧版《哈姆雷特》', 161, '[{"q":"How did the writer feel about Hamlet before seeing the opera?","answer":"A","options":["He believed he already understood the play well.","He had never heard of the play.","He found the play boring to read.","He disliked Shakespeare''s writing."],"explanation":"开头说他读过多次、自认很熟悉 Hamlet,即认为自己已经很了解这部戏。"},{"q":"What does the writer say about the stage design?","answer":"B","options":["It was crowded with real horses and furniture.","It was very simple, using a few props to suggest much more.","It used huge modern screens everywhere.","It copied a Western theatre exactly."],"explanation":"原文讲舞台几乎空荡,一根鞭子代表一匹马,简单道具营造大世界,即用极简布景暗示丰富内容。"},{"q":"Why could the writer still follow the story though it was sung in Chinese?","answer":"A","options":["The actors'' movements and emotions made the meaning clear.","There were English voices behind the stage.","He had memorised the Chinese words.","A teacher explained each line aloud."],"explanation":"原文说动作、表情把意思传达给他,他感受到剧中情感便认出了故事,即靠表演动作与情感理解。"}]'::jsonb, '[{"word":"version","cn":"版本;改编"},{"word":"string","cn":"(乐器的)弦"},{"word":"grief","cn":"悲痛"}]'::jsonb, 2, 'required2', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Good Book, Bad Movie?', 'People say that a picture is worth a thousand words, yet many great books become poor films. Why does this happen so often? One big reason is time. A book may take several days to read, but a film usually lasts under two hours. Because of this, films have to cut characters and details that readers love. Even the popular Harry Potter films left out scenes, which disappointed many fans of the books. A second reason is that films sometimes do not match the pictures in our minds. When the look of a character or place is different from what we imagined while reading, we feel let down. Some people argue, however, that a book and a film are two different forms with different rules. Perhaps, then, we should judge a film on its own and not always compare it with the book. In recent years, long television series have become a popular way to tell big stories without losing too much.', '议论·好书为何拍成烂片', 162, '[{"q":"According to the text, why do films often cut parts of a book?","answer":"B","options":["Directors have never read the books.","A film is much shorter, so it has no room for everything.","Audiences ask for shorter characters.","Books contain no interesting scenes."],"explanation":"原文说电影通常不到两小时,因此不得不删减角色和细节,即时长太短装不下全部内容。"},{"q":"What does the Harry Potter example show?","answer":"C","options":["The films were complete failures.","The books were too short to film.","Even very successful films may leave fans unhappy by cutting scenes.","Fans never noticed the missing parts."],"explanation":"原文用 Harry Potter 说明连卖座电影也删了情节、令书迷失望,即再成功的电影也会因删减让粉丝不满。"},{"q":"What does the writer suggest we do with film adaptations?","answer":"D","options":["Stop watching films based on books.","Only trust films that copy the book word for word.","Read the book after watching the film.","Judge each film by itself rather than always measuring it against the book."],"explanation":"原文建议就电影本身评价,不总拿它与原著比较。"}]'::jsonb, '[{"word":"disappointed","cn":"失望的"},{"word":"escape","cn":"逃避;避免"},{"word":"original","cn":"原版的;最初的"}]'::jsonb, 2, 'required2', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'A Review of The Princess Diaries', 'The Princess Diaries is a film about a teenager named Mia. Shortly before her sixteenth birthday, she is shocked to learn that she is the princess of a small made-up kingdom. Mia is a shy, awkward American girl, and at first she has no idea how to behave like royalty. She is taught how to act in public, but things become difficult when newspapers find out her secret and follow her everywhere. In the end she must choose between her ordinary life as a city teenager and her new duties as a princess. The film looks at the idea of responsibility in a warm and funny way. My favourite scene comes near the end, when Mia, full of self-doubt, reads a letter from her late father. His words about courage stay in my memory long after the film is over. If you enjoy a story that is both light and thoughtful, this is a film you really should not miss.', '影评·《公主日记》', 160, '[{"q":"What surprising news does Mia receive?","answer":"A","options":["She is really a princess of a small invented country.","She has won a singing contest.","She must move to another school.","Her father is a famous actor."],"explanation":"原文说她震惊地得知自己是一个虚构小王国的公主,即她其实是个公主。"},{"q":"What makes Mia''s life difficult after the news?","answer":"B","options":["She forgets how to speak English.","Reporters discover her secret and keep following her.","She loses all her money.","Her friends move abroad."],"explanation":"原文说报纸发现了她的秘密、到处跟着她,即记者曝光并追踪她。"},{"q":"What does the reviewer think of the film?","answer":"C","options":["It is dull and not worth watching.","It is too sad for young viewers.","It is enjoyable, mixing light fun with a thoughtful message.","It is good only for its music."],"explanation":"末段说它既轻松又引人思考、非常值得一看,即评价正面、轻松又有深意。"}]'::jsonb, '[{"word":"fictional","cn":"虚构的"},{"word":"behave","cn":"举止;表现"},{"word":"responsibility","cn":"责任"}]'::jsonb, 2, 'required2', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'The Glastonbury Festival', 'The Glastonbury Festival is one of the most famous music and arts festivals in the world. It began in the 1970s and takes place on a large farm in the south-west of England. Each summer, thousands of people travel there to camp for several days and enjoy live music under the open sky. What makes the festival special is not only the music but also the friendly spirit behind it. Most of the people who organise it are volunteers, and a large part of the money from ticket sales is given to charity. Over the years, many well-known bands have played there, and the crowd has grown to around two hundred thousand. Getting there takes some planning. Many visitors meet in London, take a coach to a nearby town, and then use a free bus service to reach the festival site. Because the weather can change quickly, experienced fans always pack a tent, warm clothes and a rain jacket.', '说明·格拉斯顿伯里音乐节', 159, '[{"q":"What makes the festival special besides the music?","answer":"D","options":["Its free food for every visitor.","Its location inside a big city.","Its rule that only famous people may attend.","Its kind spirit, with volunteers and money going to charity."],"explanation":"原文说组织者多为志愿者、票款大部分捐给慈善,这种友善精神让它与众不同。"},{"q":"How do many visitors usually reach the festival?","answer":"A","options":["After meeting up in the capital, they ride a coach and then a shuttle bus.","They fly directly to the farm.","They drive their own cars onto the stage.","They walk all the way from London."],"explanation":"原文描述在伦敦集合、坐长途车到附近镇、再乘免费巴士到场地。"},{"q":"Why do experienced fans bring a tent and a rain jacket?","answer":"B","options":["There are no hotels in England.","The weather there can change suddenly.","The organisers sell them at high prices.","Tents are required to enter London."],"explanation":"原文说天气可能骤变,所以有经验的人会带帐篷和雨衣。"}]'::jsonb, '[{"word":"arrangement","cn":"安排"},{"word":"transport","cn":"交通"},{"word":"extent","cn":"程度"}]'::jsonb, 2, 'required2', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'A Night at the Ballet', 'Last night I went to watch the ballet The Peony Pavilion, and it changed the way I think about dance. Before going, I believed that ballet looked more or less the same everywhere, so I was not really prepared for what I saw. As soon as the curtain rose, I was completely absorbed. This performance was not like any ballet I had seen before. It borrowed a great deal from Chinese dance and music, so the influence of Eastern art was clear in every scene. The stage was full of soft colours and romantic symbols, and the dancers'' movements challenged my eyes in new and surprising ways. The music seemed to carry the story forward without a single spoken word. By the end, I understood that ballet can speak many cultural languages at once. I enjoyed the evening so much that I can hardly wait to go again, and I now tell all my friends to give this kind of show a chance.', '记叙·芭蕾《牡丹亭》', 163, '[{"q":"What did the writer think about ballet before the show?","answer":"C","options":["That it was always boring to watch.","That only children could enjoy it.","That it was much the same wherever you saw it.","That it needed a lot of spoken words."],"explanation":"原文说他原以为芭蕾到哪儿都差不多,所以没做好心理准备。"},{"q":"What made this ballet different from others?","answer":"D","options":["It used no music at all.","It was performed without any dancers.","It was spoken rather than danced.","It blended Eastern dance and musical styles into the ballet."],"explanation":"原文说它大量借鉴中国舞蹈和音乐,东方艺术影响明显。"},{"q":"How did the writer feel by the end of the evening?","answer":"A","options":["Delighted, and eager to see such a show again.","Tired and ready to leave early.","Confused and unable to follow it.","Sorry that he had bought a ticket."],"explanation":"末段说他非常享受、迫不及待想再看,还向朋友推荐。"}]'::jsonb, '[{"word":"ballet","cn":"芭蕾舞剧"},{"word":"absorbed","cn":"入迷的"},{"word":"romantic","cn":"浪漫的"}]'::jsonb, 2, 'required2', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (10, 'Choosing a TV Programme', 'There are many kinds of television programme, and each one offers something different. A talent show, for example, lets ordinary people sing or dance in front of judges, and viewers love to see who will win. A nature documentary takes us close to wild animals that most of us would never meet in real life. A comedy makes us laugh after a long, tiring day, while a news programme keeps us up to date with what is happening in the world. Some people enjoy a talk show, where a host chats with guests about their lives; a good host listens carefully and lets the guests speak, but a rude one talks over them and spoils the fun. Cartoons, with their creative plots and bright settings, are loved by both children and adults. When friends share their favourite programmes, they often describe them with strong words such as exciting, appealing or unforgettable. In the end, the best programme is simply the one that you enjoy most.', '说明·电视节目类型', 165, '[{"q":"What does a talent show let people do?","answer":"B","options":["Watch wild animals in nature.","Sing or dance before a panel and try to win.","Read the daily news.","Buy and sell goods on screen."],"explanation":"原文说选秀节目让普通人在评委面前唱歌跳舞,观众期待谁会获胜。"},{"q":"What is the difference between a good and a rude talk-show host?","answer":"C","options":["A good one never invites any guests.","A rude one always sings to the guests.","A polite host allows guests to talk, but a rude one keeps interrupting.","A good one refuses to ask questions."],"explanation":"原文对比:好主持人认真听、让嘉宾说;无礼的主持人抢话,破坏乐趣。"},{"q":"What does the writer say is the best programme?","answer":"D","options":["Only the news programme.","The one with the most famous host.","The longest programme on TV.","Whatever programme a person enjoys the most."],"explanation":"末句说最好的节目就是你自己最喜欢的那个。"}]'::jsonb, '[{"word":"documentary","cn":"纪录片"},{"word":"comedy","cn":"喜剧"},{"word":"appealing","cn":"有吸引力的"}]'::jsonb, 2, 'required2', 'U4', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U4', 'My First Time on Stage', 'Today I performed in the school play, and I think I did a good (1)____ job. When I first saw all my family and friends in the (2)____, I felt both nervous and proud. At the start of rehearsals, I had not (3)____ how much hard work the play would be. Our teacher was very strict, which sometimes made me so (4)____ that I was afraid I would forget my lines. I often stayed up late at night to (5)____ my part again and again. There were moments when I felt so discouraged that I almost (6)____ up. But thanks to the support of the people around me, I slowly (7)____ my fears. When the curtain finally rose, I tried to (8)____ calm and remember every word. By the end, the whole audience began to (9)____, and I felt extremely (10)____ to everyone who had helped me. It was truly an unforgettable experience.', 153, 2, '[{"q":"1","answer":"A","options":["job","test","trip","meal"],"explanation":"do a good job 做得不错,固定搭配。"},{"q":"2","answer":"B","options":["kitchen","audience","library","market"],"explanation":"看戏的家人朋友坐在观众席,用 audience。"},{"q":"3","answer":"C","options":["refused","repaired","realised","returned"],"explanation":"had not realised 此前没意识到,符合语境。"},{"q":"4","answer":"D","options":["proud","polite","lazy","nervous"],"explanation":"老师严格使我紧张到怕忘词,用 nervous。"},{"q":"5","answer":"A","options":["practise","sell","draw","clean"],"explanation":"熬夜反复练习角色台词,用 practise。"},{"q":"6","answer":"B","options":["looked","gave","stood","woke"],"explanation":"give up 放弃,固定搭配。"},{"q":"7","answer":"C","options":["counted","missed","overcame","borrowed"],"explanation":"在支持下慢慢克服恐惧,用 overcame。"},{"q":"8","answer":"D","options":["leave","fall","grow","stay"],"explanation":"stay calm 保持冷静,固定搭配。"},{"q":"9","answer":"A","options":["clap","cook","drive","sleep"],"explanation":"演出结束观众开始鼓掌,用 clap。"},{"q":"10","answer":"B","options":["angry","grateful","bored","afraid"],"explanation":"对帮助过自己的人感到感激,用 grateful。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U4', 'Planning a Trip to a Comedy Show', 'Last weekend my friends and I decided to go to a (1)____ show in another part of the city. None of us had been there before, so we needed to make careful (2)____. First we checked online and found that the tickets were not (3)____, which was good news for students like us. Then we had to work out how to get there. Since the theatre was far away, we chose to use public (4)____ instead of taxis. Josh, who is always well organised, offered to (5)____ everything for the group. He told us where to (6)____ and what time the first bus would leave. On the night of the show, we arrived early so that we could find good (7)____. The moment the host walked onto the stage, everyone began to (8)____ loudly. The jokes were so funny that we (9)____ all evening. By the time we left, we all agreed it had been an (10)____ night out.', 159, 2, '[{"q":"1","answer":"C","options":["garden","village","comedy","weather"],"explanation":"去看喜剧表演,用 comedy。"},{"q":"2","answer":"D","options":["mistakes","promises","drawings","arrangements"],"explanation":"make arrangements 做安排,符合语境。"},{"q":"3","answer":"A","options":["expensive","quiet","heavy","early"],"explanation":"票不贵,对学生是好消息,用 expensive。"},{"q":"4","answer":"B","options":["weather","transport","homework","music"],"explanation":"public transport 公共交通,固定搭配。"},{"q":"5","answer":"C","options":["cook","paint","arrange","wash"],"explanation":"Josh 提出为大家安排好一切,用 arrange。"},{"q":"6","answer":"D","options":["sing","swim","shop","meet"],"explanation":"告诉我们在哪儿集合,用 meet。"},{"q":"7","answer":"A","options":["seats","clothes","books","meals"],"explanation":"早到是为了找到好座位,用 seats。"},{"q":"8","answer":"B","options":["cry","applaud","complain","leave"],"explanation":"主持人上台时大家大声鼓掌,用 applaud。"},{"q":"9","answer":"C","options":["slept","argued","laughed","studied"],"explanation":"笑话太好笑,我们笑了一整晚,用 laughed。"},{"q":"10","answer":"D","options":["boring","ordinary","difficult","unforgettable"],"explanation":"大家一致认为是难忘的一晚,用 unforgettable。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U4', 'Making the Costumes', 'Behind every good play there is a team of people you never (1)____ on stage. This term I joined the group that makes the (2)____ for our school drama. At first I thought sewing clothes would be (3)____, but I soon learned how hard it really is. Each costume has to match the (4)____ of the story, so we read the script many times before we (5)____ anything. We chose soft colours for the gentle scenes and bright ones for the (6)____ moments. Our teacher showed us a few clever (7)____ for turning cheap cloth into something that looked rich and old. Sometimes a small mistake meant we had to (8)____ the whole thing and begin again. It was tiring work, but when the actors finally (9)____ our costumes on stage, I felt incredibly (10)____ of what our team had done.', 141, 2, '[{"q":"1","answer":"A","options":["see","eat","buy","drive"],"explanation":"幕后有些人你在台上永远看不到,用 see。"},{"q":"2","answer":"B","options":["tickets","costumes","lessons","dinners"],"explanation":"为校园戏剧做戏服,用 costumes。"},{"q":"3","answer":"C","options":["loud","wet","easy","late"],"explanation":"起初以为缝衣服很容易,用 easy。"},{"q":"4","answer":"D","options":["price","weather","noise","mood"],"explanation":"戏服要与故事的情绪/气氛相配,用 mood。"},{"q":"5","answer":"A","options":["cut","sing","sleep","shout"],"explanation":"动手剪裁前先反复读剧本,用 cut。"},{"q":"6","answer":"B","options":["quiet","exciting","empty","cheap"],"explanation":"与 gentle 的柔和场景相对,激动场面用亮色,用 exciting。"},{"q":"7","answer":"C","options":["stories","songs","techniques","prices"],"explanation":"老师教了几招把廉价布料变华贵的技巧,用 techniques。"},{"q":"8","answer":"D","options":["enjoy","praise","keep","undo"],"explanation":"小错误意味着要拆掉重来,用 undo。"},{"q":"9","answer":"A","options":["wore","ate","bought","washed"],"explanation":"演员最终穿着我们的戏服上台,用 wore。"},{"q":"10","answer":"B","options":["afraid","proud","sorry","tired"],"explanation":"为团队的成果感到自豪,用 proud。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U4', 'Learning to Love Opera', 'I used to believe that opera was only for old people, and I never (1)____ to give it a try. Then my grandmother took me to see a famous (2)____ in our city, and my opinion changed completely. As soon as the lights went down, I felt (3)____ by the sound of the orchestra. The voices were so powerful that they seemed to fill the whole (4)____. Even though I could not understand every word, the music helped me (5)____ what the singers were feeling. There were moments of love, (6)____ and sadness, all carried by the music alone. I sat on the (7)____ of my seat, afraid to miss a single note. During the most exciting scene, the audience could not help but (8)____. By the end of the evening, I was (9)____ amazed by what I had seen and heard. Now I tell my friends that opera is far more (10)____ than they think.', 156, 2, '[{"q":"1","answer":"C","options":["promised","managed","wanted","remembered"],"explanation":"以前从不想尝试,用 wanted。"},{"q":"2","answer":"D","options":["garden","market","station","opera"],"explanation":"祖母带我去看著名歌剧,用 opera。"},{"q":"3","answer":"A","options":["absorbed","bored","frightened","tired"],"explanation":"被乐队的声音深深吸引,用 absorbed。"},{"q":"4","answer":"B","options":["kitchen","theatre","garden","office"],"explanation":"歌声充满整个剧院,用 theatre。"},{"q":"5","answer":"C","options":["forget","sell","understand","build"],"explanation":"音乐帮我理解歌者的感受,用 understand。"},{"q":"6","answer":"D","options":["lunch","money","weather","anger"],"explanation":"与 love、sadness 并列的情感,用 anger。"},{"q":"7","answer":"A","options":["edge","top","back","side"],"explanation":"on the edge of one''s seat 坐在座位边缘(极为投入),固定搭配。"},{"q":"8","answer":"B","options":["cook","clap","run","shop"],"explanation":"最激动的场面观众忍不住鼓掌,用 clap。"},{"q":"9","answer":"C","options":["hardly","rarely","completely","never"],"explanation":"结束时完全被震撼,用 completely。"},{"q":"10","answer":"D","options":["boring","useless","ordinary","appealing"],"explanation":"告诉朋友歌剧比想象的有趣得多,用 appealing。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U4', 'The School Film Club', 'Our school film club meets every Friday after class, and it has become my favourite part of the (1)____. Each week a different member chooses a film for everyone to (2)____ together. After the film ends, we sit in a circle and (3)____ what we have just seen. Some people love a story with a clever (4)____, while others care most about the acting. Last month we watched a film that was (5)____ on a famous novel, and we argued for an hour about whether the book or the film was (6)____. I learned that two people can watch the same story and still have very (7)____ opinions. Our teacher says this is exactly why talking about films is so (8)____. She encourages us to give reasons instead of simply saying we (9)____ or hated something. Thanks to the club, I now watch every film much more (10)____ than I used to.', 152, 2, '[{"q":"1","answer":"A","options":["week","meal","road","shop"],"explanation":"电影社是我一周中最喜欢的部分,用 week。"},{"q":"2","answer":"B","options":["cook","watch","drive","build"],"explanation":"选一部电影让大家一起看,用 watch。"},{"q":"3","answer":"C","options":["forget","sell","discuss","draw"],"explanation":"看完后围坐讨论刚看的内容,用 discuss。"},{"q":"4","answer":"D","options":["price","noise","smell","plot"],"explanation":"有人喜欢情节巧妙的故事,用 plot。"},{"q":"5","answer":"A","options":["based","sat","put","kept"],"explanation":"be based on 改编自,固定搭配,用 based。"},{"q":"6","answer":"B","options":["louder","better","shorter","colder"],"explanation":"争论书和电影哪个更好,用 better。"},{"q":"7","answer":"C","options":["quiet","heavy","different","empty"],"explanation":"两人看同一故事却有很不同的看法,用 different。"},{"q":"8","answer":"D","options":["boring","useless","tiring","interesting"],"explanation":"老师说这正是谈电影有趣的原因,用 interesting。"},{"q":"9","answer":"A","options":["loved","feared","sold","lost"],"explanation":"与 hated 相对,用 loved。"},{"q":"10","answer":"B","options":["quickly","carefully","rarely","loudly"],"explanation":"现在看每部电影都比以前更仔细,用 carefully。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (10, 'required2', 'U4', 'Filming a Wildlife Documentary', 'Making a wildlife (1)____ is far harder than most viewers imagine. To film leopards in the wild, a small team may have to (2)____ for weeks in a hot, distant place. The camera operators must stay very (3)____ so that the animals are not frightened away. Sometimes they wait all day and (4)____ nothing at all. When a leopard and her cubs finally appear, the team has only a few (5)____ to capture the perfect picture. Every member of the crew has an important (6)____ to play, from carrying the heavy equipment to checking the sound. The pictures they bring back can (7)____ the way ordinary people see nature. Many viewers, (8)____ by what they watch, begin to care more about protecting wild animals. That is why the team believes their tiring work is (9)____ worth it. A good documentary, they say, can teach more than any (10)____ book.', 149, 2, '[{"q":"1","answer":"C","options":["comedy","garden","documentary","lesson"],"explanation":"制作野生动物纪录片,用 documentary。"},{"q":"2","answer":"D","options":["sing","shop","sleep","wait"],"explanation":"团队可能在炎热偏远处等上数周,用 wait。"},{"q":"3","answer":"A","options":["quiet","angry","proud","rude"],"explanation":"必须保持安静以免吓跑动物,用 quiet。"},{"q":"4","answer":"B","options":["eat","see","buy","build"],"explanation":"有时等一整天却什么也看不到,用 see。"},{"q":"5","answer":"C","options":["weeks","months","minutes","years"],"explanation":"豹子出现时只有几分钟抓拍,用 minutes。"},{"q":"6","answer":"D","options":["ticket","meal","price","part"],"explanation":"have a part to play 各司其职,固定搭配,用 part。"},{"q":"7","answer":"A","options":["change","sell","wash","close"],"explanation":"这些画面能改变普通人看待自然的方式,用 change。"},{"q":"8","answer":"B","options":["bored","moved","paid","sold"],"explanation":"许多观众被所看内容打动(被动),用 moved。"},{"q":"9","answer":"C","options":["hardly","rarely","certainly","never"],"explanation":"团队相信辛苦的工作当然值得,用 certainly。"},{"q":"10","answer":"D","options":["ticket","garden","engine","textbook"],"explanation":"好纪录片比任何课本教得更多,用 textbook。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U4 听力·对话 Booking Opera Tickets', '外研社版必修第二册 U4 · dialogue', 3, 'Clerk: Good afternoon, City Theatre box office. How can I help you?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U4 听力·独白 My First Ballet Lesson', '外研社版必修第二册 U4 · passage', 2, 'Last month I went to my very first ballet lesson, and I was extremely nervous. I had always loved watching dancers move so gracefully on stage, but I had never tried it myself. At the beginning, even standing correctly felt difficult, and my legs ached after only ten minutes. My teacher was kind and patient. She told me that every great dancer was once a beginner, and that hard work matters far more than talent. Little by little, I began to enjoy each movement. Now I practise at home every evening, and I dream of dancing in a real performance one day.', '上个月我第一次上芭蕾课,非常紧张。我一直喜欢看舞者在台上优雅起舞,却从没自己试过。一开始连站姿都很难,十分钟后腿就酸了。老师友善又耐心,告诉我每位伟大舞者都曾是初学者,努力比天赋更重要。渐渐地我开始享受每个动作。如今我每晚在家练习,梦想有朝一日能在真正的演出中起舞。', 'uk_female', '[{"q":"How did the speaker feel at her first lesson?","type":"choice","answer":"D","options":["Completely bored.","Quite angry.","Rather sleepy.","Very nervous."]},{"q":"What was difficult for her at the beginning?","type":"choice","answer":"A","options":["Even standing in the correct way.","Remembering the teacher''s name.","Finding the dance studio.","Paying for the lesson."]},{"q":"What did her teacher say matters most?","type":"choice","answer":"B","options":["Wearing the most expensive shoes.","Hard work rather than natural talent.","Being born into a dancing family.","Starting at a very young age."]},{"q":"What does the speaker do now every evening?","type":"choice","answer":"C","options":["She watches comedy shows.","She writes film reviews.","She practises ballet at home.","She teaches other beginners."]},{"q":"What is the speaker''s dream?","type":"choice","answer":"D","options":["To open her own theatre.","To become a film director.","To stop dancing forever.","To dance in a real performance one day."]}]'::jsonb, '[]'::jsonb, 'short', 'required2', 'U4', 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U4 听力·对话 What Shall We Watch Tonight?', '外研社版必修第二册 U4 · dialogue', 3, 'Mum: There''s nothing good on TV tonight. What would you like to watch, Lily?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U4 听力·独白 Comedy Club Advertisement', '外研社版必修第二册 U4 · passage', 2, 'Are you looking for a fun way to spend your weekend? Come to the Riverside Comedy Club, the brightest place in town for a good laugh. Every Friday and Saturday night, our stage welcomes some of the funniest performers in the country. Doors open at half past seven, and the show begins at eight. Tickets cost just fifteen pounds, and students pay only ten. Seats fill up quickly, so we strongly advise you to book early online. Bring your friends, leave your worries at home, and get ready for an evening full of jokes and laughter. We promise you will not be disappointed.', '想找个有趣的方式过周末吗?来河畔喜剧俱乐部——城里最欢乐的地方。每周五、周六晚,我们的舞台迎来全国最搞笑的表演者。七点半开门,八点开演。门票仅15英镑,学生只需10英镑。座位很快售罄,强烈建议提前网上订票。带上朋友,把烦恼留在家里,准备好享受充满笑声的夜晚。我们保证你不会失望。', 'uk_male', '[{"q":"What kind of place is being advertised?","type":"choice","answer":"B","options":["A swimming pool.","A comedy club.","A bookshop.","A train station."]},{"q":"On which nights are there shows?","type":"choice","answer":"C","options":["Monday and Tuesday.","Only on Sunday.","Friday and Saturday.","Every night of the week."]},{"q":"What time does the show begin?","type":"choice","answer":"D","options":["At half past seven.","At nine o''clock.","At noon.","At eight o''clock."]},{"q":"How much do students pay?","type":"choice","answer":"A","options":["Ten pounds.","Fifteen pounds.","Five pounds.","Twenty pounds."]},{"q":"What does the advertisement advise listeners to do?","type":"choice","answer":"B","options":["Arrive after the show starts.","Book their tickets early online.","Come without any friends.","Pay at the door in cash."]}]'::jsonb, '[]'::jsonb, 'short', 'required2', 'U4', 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U4 听力·对话 Travelling to a Concert', '外研社版必修第二册 U4 · dialogue', 3, 'Anna: I''ve got two tickets for the concert in Manchester next Saturday. Do you want to come?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (10, 'U4 听力·独白 A Film I Saw Last Night', '外研社版必修第二册 U4 · passage', 2, 'Last night I watched a film that was based on a famous novel I had read at school. I went in expecting to be disappointed, because films often leave out my favourite parts of a story. To my surprise, this one was different. The director kept the main plot and most of the important characters, and the acting was wonderful. Of course, a few scenes were missing, but the film still captured the spirit of the book. By the end, I was deeply moved, and several people in the cinema were quietly clapping. I would definitely recommend it, whether or not you have read the original story.', '昨晚我看了一部根据我上学时读过的著名小说改编的电影。本以为会失望,因为电影常删掉我最喜欢的情节。出乎意料,这部不同:导演保留了主线和大多数重要角色,表演也很棒。当然有几场戏被删了,但电影仍抓住了原著的精神。看到最后我深受感动,影院里有几个人在轻轻鼓掌。无论你是否读过原著,我都强烈推荐。', 'uk_male', '[{"q":"What was the film based on?","type":"choice","answer":"D","options":["A true news story.","A children''s cartoon.","The speaker''s own life.","A famous novel the speaker had read."]},{"q":"Why did the speaker expect to be disappointed?","type":"choice","answer":"A","options":["Films often cut his favourite parts of a story.","He dislikes all films.","The cinema was far away.","The tickets were expensive."]},{"q":"What did the director keep in the film?","type":"choice","answer":"B","options":["Only the title of the book.","The main plot and most important characters.","None of the original story.","Just the final scene."]},{"q":"How did the speaker feel by the end?","type":"choice","answer":"C","options":["Extremely bored.","Quite angry.","Deeply moved.","Rather sleepy."]},{"q":"What does the speaker advise?","type":"choice","answer":"D","options":["He tells people to avoid it.","He says to read the book instead.","He warns it is only for children.","He recommends the film to everyone."]}]'::jsonb, '[]'::jsonb, 'short', 'required2', 'U4', 'fltrp');
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (10, 'Write a Movie Review(写一篇电影影评)', 'A Movie Review', '假设你叫李华,学校英语社团要办一期“我最喜欢的电影”墙报。请用英语写一篇约100词的影评,内容包括:① 总体介绍这部电影(片名、类型、主要演员或导演);② 简述主要情节和一个最难忘的场景;③ 给出你的评价并说明是否推荐。注意:适当使用 -ing 分词作状语(如 Watching the film, …)。', 'Suppose you are Li Hua. Your school English club is making a wall display called "My Favourite Film". Write a movie review of about 100 words including: 1) a general introduction to the film (its title, type, and main actor or director); 2) a short summary of the plot and one unforgettable scene; 3) your opinion and whether you recommend it. Try to use -ing participles as adverbials (e.g. Watching the film, …).', '["总体介绍(… is a … film about … / Starring …, it …)","情节与难忘场景(The story follows … / The most memorable scene is …)","评价与推荐(I think it is … / I would definitely recommend it because …)","用 -ing 分词作状语(Watching the film, I … / Feeling the emotions, …)"]'::jsonb, 70, 100, 'The Princess Diaries is a warm and funny film about a shy teenager named Mia. Starring Anne Hathaway, it tells how an ordinary city girl suddenly learns that she is the princess of a small fictional kingdom. The story follows Mia as she struggles to behave like royalty while reporters follow her everywhere. The most memorable scene comes near the end, when Mia reads a letter from her late father about courage. Watching that moment, I could not hold back my tears. The film explores responsibility in a light and clever way. I would definitely recommend it to anyone who enjoys a story that is both fun and thoughtful.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["Starring Anne Hathaway, it tells how an ordinary city girl becomes a princess.","The story follows Mia as she struggles to behave like royalty.","Watching that moment, I could not hold back my tears.","I would definitely recommend it to anyone who enjoys a thoughtful story."]'::jsonb, '[{"wrong":"The film is about how Mia becoming a princess.","correct":"The film is about how Mia becomes a princess.","note":"how 引导的从句要用完整谓语 becomes,不用分词 becoming。"},{"wrong":"Watched the film, I was deeply moved.","correct":"Watching the film, I was deeply moved.","note":"逻辑主语 I 主动观看,作状语用现在分词 Watching,不用过去分词。"},{"wrong":"I recommend it for everyone who likes stories.","correct":"I recommend it to everyone who likes stories.","note":"recommend sth to sb 固定搭配,用 to 不用 for。"}]'::jsonb, '【影评结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (10, 'required2', 'U4', '{"title":"-ing 分词作状语速查(时间 / 原因 / 伴随 + 与 -ed 的区别)","intro":"现在分词(-ing)可放在句首或句中作状语,表示时间、原因或伴随。判断口诀:看状语的逻辑主语(=主句主语)——主语主动做这个动作用 -ing,主语承受这个动作(常带 by)用 -ed。","table":{"headers":["用法","相当于 / 例句"],"rows":[["时间(同时发生)","= when/while/as:Watching the play, the audience held their breath."],["原因","= because/as/since:Being a big fan, she watched it three times."],["伴随情况","与谓语同时进行:She walked on, smiling at the crowd."],["主动 -ing vs 被动 -ed","Facing the crowd, he bowed.(主动) / Encouraged by the applause, he bowed again.(被动)"]]},"specialRules":[{"rule":"逻辑主语主动发出动作 → 用现在分词 -ing","mark":"Hearing the song, the children clapped.(孩子主动听)"},{"rule":"逻辑主语承受动作、常带 by → 用过去分词 -ed","mark":"Moved by the music, they fell silent.(他们被打动)"},{"rule":"句首表原因常用 Being / Having / Not + doing","mark":"Not knowing the plot, the guests felt lost."},{"rule":"分词的逻辑主语必须与主句主语一致,否则成‘垂悬分词’","mark":"Watching the film, I cried.(主语都是 I)√"}],"why":["现在分词没有时间和被动的标记,它的‘谁来做’要靠主句主语来补;主句主语既是谓语动作的执行者,也是分词动作的执行者,所以主动用 -ing、被动用 -ed,关键看主语和这个动作是主动还是被动关系。"],"gaokaoPoints":["现在分词 vs 过去分词作状语的判断(主动 -ing / 被动 -ed),语法填空与短文改错高频。","句首 -ing 表原因或时间,逻辑主语必须与主句主语一致;to do 表目的、谓语动词形式都不能作此类状语。"],"examVsReal":[{"exam":"Watching the play, the audience held their breath.（考试/书面)","real":"The audience held their breath as they watched the play.","note":"考试爱考分词状语;口语里更常用 when/as 加完整从句,意思相同。"},{"exam":"Not knowing the answer, she stayed silent.（考试)","real":"She stayed silent because she didn''t know the answer.","note":"考试用句首分词表原因;日常表达常直接用 because 从句,更口语化。"}]}'::jsonb, 'fltrp');
